/*
 * tests/test_api_layout.c -- the API description agrees with the headers.
 *
 * sdk/api/v4/layout_check.c is generated by tools/apigen.py from its own
 * reading of the headers; it holds one static assertion per payload field,
 * so a description that has drifted from sdk/mod_api.h does not compile.
 * The test that the committed description is the generator's current
 * output is the apigen_check test (tools/apigen.py --check).
 */

#include <stdio.h>

#include "api/v4/layout_check.c"

int main(void)
{
    printf("test_api_layout: the payload offsets of sdk/api/v4 match the headers\n");
    return 0;
}
